'use client';

import { Children, type FormEvent, isValidElement, type ReactElement, type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ArrowRight, Boxes, Briefcase, Building2, Check, CheckCircle2, ChevronDown, CircleDot, Copy, Database, Factory, FileCode2, FolderGit2, GitBranch, GitCommitHorizontal, History, Import, Info, Landmark, Languages, Layers3, Monitor, Moon, MoreHorizontal, Package, Pencil, Plus, RotateCcw, Search, Server, Settings, SlidersHorizontal, Store, Sun, Table2, Trash2, Upload, Warehouse, XCircle } from 'lucide-react';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DropdownMenu, DropdownMenuCheckboxItem, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Textarea } from '@/components/ui/textarea';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';

type Project={id:string;code:string;name:string;kind:'platform'|'project';parentId:string|null;icon:string;description:string;environmentCount:number;versionCount:number;fieldCount:number};
type Environment={id:string;projectId:string;versionId:string|null;code:string;name:string;stage:string;sortOrder:number;projectName:string;versionName:string|null;fieldCount:number};
type Version={id:string;projectId:string;name:string;sourceVersion:string|null;repositoryId:string|null;gitRef:string|null;gitCommit:string|null;status:string;projectName:string;repositoryName:string|null;repository:string|null};
type Module={id:string;code:string;name:string;description:string;tableCount:number;projectCount:number};
type TableItem={id:string;code:string;name:string;comment:string;moduleId:string|null;moduleName:string|null;fieldCount:number};
type FieldItem={id:string;code:string;name:string;dataType:string;nullable:number;defaultValue:string|null;comment:string;extra:string;sourceKind:string;tableId:string;tableName:string;tableCode:string;moduleName:string|null;projectNames:string|null;environmentNames:string|null;scopeCount:number};
type Scope={fieldId:string;projectId:string;versionId:string;environmentId:string;state:string;origin:string};
type ImportBatch={id:string;code:string;name:string;sourceKind:string;fileName:string|null;sourcePath?:string|null;gitCommit?:string|null;status:string;addedCount:number;duplicateCount:number;conflictCount:number;createdAt:string;projectId:string;versionId:string;moduleId?:string|null;projectName:string;versionName:string;moduleName?:string|null;environmentIds?:string|null;environmentNames?:string|null;rawSql?:string};
type ImportItem={id:string;statementNo:number;action:string;tableName:string;columnName:string;result:string;message:string};
type ImportInsight={batch:ImportBatch&{repository?:string|null;repositoryBranch?:string|null;gitRef?:string|null};items:ImportItem[]};
type EnvironmentInsight={environment:Environment&{parentId:string|null};coverage:{expectedCount:number;presentCount:number}|null;missing:{id:string;code:string;name:string;dataType:string;comment:string;tableName:string}[];imports:ImportBatch[]};
type Repository={id:string;name:string;repository:string;branch:string;pathPattern:string;projectId:string|null;lastCommit:string|null;enabled:number};
type CatalogData={projects:Project[];environments:Environment[];versions:Version[];modules:Module[];tables:TableItem[];fields:FieldItem[];scopes:Scope[];fieldTotal:number;imports:ImportBatch[];repositories:Repository[]};
type ProjectDifference={id:string;code:string;name:string;dataType:string;comment:string;tableName:string;versionId:string;versionName:string;totalCount:number;presentCount:number;missingEnvironments:string|null};
type ProjectInsight={differences:ProjectDifference[];imports:ImportBatch[]};
type View='explorer'|'projects'|'imports'|'settings';
type ModalKind='project'|'environment'|'version'|'module'|'table'|'field'|'repository'|null;
type Confirmation={title:string;description:string;confirmLabel:string;run:()=>Promise<void>};

const empty:CatalogData={projects:[],environments:[],versions:[],modules:[],tables:[],fields:[],scopes:[],fieldTotal:0,imports:[],repositories:[]};
const emptySelect='__drifty_empty__';
const projectIconOptions=[{value:'server',icon:Server},{value:'package',icon:Package},{value:'building',icon:Building2},{value:'briefcase',icon:Briefcase},{value:'factory',icon:Factory},{value:'warehouse',icon:Warehouse},{value:'store',icon:Store},{value:'landmark',icon:Landmark},{value:'boxes',icon:Boxes}] as const;
const words={
zh:{landscape:'全景',projects:'项目',structure:'结构',imports:'导入',settings:'设置',search:'搜索',theme:'主题',system:'系统',light:'浅色',dark:'深色',platform:'平台',customerProject:'项目',environment:'环境',version:'版本',fields:'字段',tables:'表',modules:'模块',addProject:'新增项目',addEnvironment:'新增环境',addVersion:'新增版本',addModule:'新增模块',addTable:'新增表',addField:'新增字段',addSource:'新增来源',edit:'编辑',remove:'删除',save:'保存',cancel:'取消',name:'名称',code:'编码',kind:'类型',description:'说明',parentPlatform:'来源平台',stage:'阶段',sort:'顺序',sourceVersion:'来源版本',tableName:'表名',tableComment:'表注释',fieldName:'字段名',dataType:'类型',comment:'注释',defaultValue:'默认值',nullable:'可空',targetProject:'项目',targetVersion:'版本',targetEnvs:'环境',ownerModule:'模块',repository:'仓库',branch:'分支',pathPattern:'路径',upload:'上传',runImport:'导入',recentImports:'记录',reset:'清空结构',revert:'撤销',unknown:'未分类',saved:'已保存',deleted:'已删除',loadError:'读取失败',confirmDelete:'确认删除？',confirmRevert:'确认撤销整批导入？',confirmReset:'确认清空全部结构数据？',noData:'暂无数据'},
en:{landscape:'Overview',projects:'Projects',structure:'Schema',imports:'Import',settings:'Settings',search:'Search',theme:'Theme',system:'System',light:'Light',dark:'Dark',platform:'Platform',customerProject:'Project',environment:'Environment',version:'Version',fields:'Fields',tables:'Tables',modules:'Modules',addProject:'New project',addEnvironment:'New environment',addVersion:'New version',addModule:'New module',addTable:'New table',addField:'New field',addSource:'New source',edit:'Edit',remove:'Delete',save:'Save',cancel:'Cancel',name:'Name',code:'Code',kind:'Kind',description:'Description',parentPlatform:'Platform',stage:'Stage',sort:'Order',sourceVersion:'Source version',tableName:'Table',tableComment:'Table comment',fieldName:'Field',dataType:'Type',comment:'Comment',defaultValue:'Default',nullable:'Nullable',targetProject:'Project',targetVersion:'Version',targetEnvs:'Environments',ownerModule:'Module',repository:'Repository',branch:'Branch',pathPattern:'Path',upload:'Upload',runImport:'Import',recentImports:'History',reset:'Reset schema',revert:'Revert',unknown:'Unclassified',saved:'Saved',deleted:'Deleted',loadError:'Could not load',confirmDelete:'Delete this item?',confirmRevert:'Revert this import?',confirmReset:'Reset all schema data?',noData:'No data'},
} as const;

function number(value:unknown){return typeof value==='number'?value:Number(value)||0;}
function ProjectIcon({name,className='size-4'}:{name:string;className?:string}){const option=projectIconOptions.find(item=>item.value===name);const Icon=option?.icon??Boxes;return <Icon className={className}/>;}
function ProjectIconPicker({defaultValue}:{defaultValue:string}){const [value,setValue]=useState(defaultValue||'boxes');return <div className="grid grid-cols-9 gap-1"><input type="hidden" name="icon" value={value}/>{projectIconOptions.map(option=>{const Icon=option.icon;return <button key={option.value} type="button" aria-label={option.value} aria-pressed={value===option.value} onClick={()=>setValue(option.value)} className={`grid aspect-square place-items-center rounded-lg border transition-colors ${value===option.value?'border-foreground bg-foreground text-background':'border-transparent bg-muted/60 text-muted-foreground hover:text-foreground'}`}><Icon className="size-4"/></button>})}</div>;}

export default function Home(){
const [data,setData]=useState<CatalogData>(empty);const [view,setView]=useState<View>('explorer');const [locale,setLocale]=useState<'zh'|'en'>('zh');const [theme,setTheme]=useState<'system'|'light'|'dark'>('system');const [query,setQuery]=useState('');const [selectedField,setSelectedField]=useState<{field:FieldItem;scopes:Scope[]}|null>(null);const [selectedProject,setSelectedProject]=useState<Project|null>(null);const [selectedEnvironment,setSelectedEnvironment]=useState<Environment|null>(null);const [selectedImport,setSelectedImport]=useState<string|null>(null);const [projectTab,setProjectTab]=useState<'differences'|'history'|'environments'>('differences');const [modal,setModal]=useState<ModalKind>(null);const [editing,setEditing]=useState<Record<string,unknown>>({});const [confirmation,setConfirmation]=useState<Confirmation|null>(null);const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [scopeProject,setScopeProject]=useState('');const [scopeVersion,setScopeVersion]=useState('');const [scopeEnvs,setScopeEnvs]=useState<string[]>([]);const [importName,setImportName]=useState('');const [importSql,setImportSql]=useState('');const [importFile,setImportFile]=useState('');const [importModule,setImportModule]=useState('');const [importSourcePath,setImportSourcePath]=useState('');const [importGitCommit,setImportGitCommit]=useState('');const t=words[locale];
const noticeTimer=useRef<number|null>(null);
const load=async()=>{const response=await fetch('/api/catalog');if(!response.ok)throw new Error('load');setData(await response.json() as CatalogData);};
useEffect(()=>{const timer=window.setTimeout(()=>{const savedLocale=localStorage.getItem('drifty-locale')==='en'?'en':'zh';const savedTheme=localStorage.getItem('drifty-theme') as 'system'|'light'|'dark'|null;setLocale(savedLocale);setTheme(savedTheme??'system');document.documentElement.lang=savedLocale==='zh'?'zh-CN':'en';document.documentElement.dataset.theme=savedTheme??'system';load().catch(()=>setNotice(words[savedLocale].loadError));},0);return()=>window.clearTimeout(timer);},[]);
const projects=useMemo(()=>data.projects.map(item=>({...item,environmentCount:number(item.environmentCount),versionCount:number(item.versionCount),fieldCount:number(item.fieldCount)})),[data.projects]);
const environments=useMemo(()=>data.environments.map(item=>({...item,fieldCount:number(item.fieldCount),sortOrder:number(item.sortOrder)})),[data.environments]);
const projectEnvs=(projectId:string)=>environments.filter(item=>item.projectId===projectId);const projectVersions=(projectId:string)=>data.versions.filter(item=>item.projectId===projectId);
const call=async(action:string,payload:Record<string,unknown>={})=>{setBusy(true);try{const response=await fetch('/api/catalog',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,payload})});const result=await response.json() as Record<string,unknown>;if(!response.ok)throw new Error(String(result.error??'保存失败'));await load();return result;}finally{setBusy(false);}};
const toast=(message:string)=>{if(noticeTimer.current!==null)window.clearTimeout(noticeTimer.current);setNotice(message);noticeTimer.current=window.setTimeout(()=>{setNotice('');noticeTimer.current=null;},1800);};
const chooseLocale=(next:'zh'|'en')=>{setLocale(next);localStorage.setItem('drifty-locale',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';};
const cycleTheme=()=>{const next=theme==='system'?'light':theme==='light'?'dark':'system';setTheme(next);localStorage.setItem('drifty-theme',next);document.documentElement.dataset.theme=next;};const themeLabel=theme==='system'?t.system:theme==='light'?t.light:t.dark;
const chooseScopeProject=(projectId:string)=>{setScopeProject(projectId);setScopeVersion(projectVersions(projectId)[0]?.id??'');setScopeEnvs(projectEnvs(projectId).map(item=>item.id));};
const go=(next:View)=>{setView(next);if(next==='imports'&&!scopeProject&&projects[0])chooseScopeProject(projects[0].id);};
const open=(kind:Exclude<ModalKind,null>,record:Record<string,unknown>={})=>{setEditing(record);setModal(kind);if(kind==='field'){const supplied=Array.isArray(record.__scopes)?record.__scopes as Scope[]:null;const existing=supplied??data.scopes.filter(scope=>scope.fieldId===record.id);const first=existing[0];if(first){setScopeProject(first.projectId);setScopeVersion(first.versionId);setScopeEnvs(existing.filter(scope=>scope.projectId===first.projectId&&scope.versionId===first.versionId).map(scope=>scope.environmentId));}else chooseScopeProject(String(record.projectId??projects[0]?.id??''));}if(kind==='environment'||kind==='version')setScopeProject(String(record.projectId??projects[0]?.id??''));};
const close=()=>{setModal(null);setEditing({});};
const submitSimple=async(event:FormEvent<HTMLFormElement>,action:string)=>{event.preventDefault();const raw=Object.fromEntries(new FormData(event.currentTarget).entries());const values=Object.fromEntries(Object.entries(raw).map(([key,value])=>[key,value===emptySelect?'':value]));const payload={...editing,...values};try{await call(action,payload);close();toast(t.saved);}catch(error){toast(error instanceof Error?error.message:String(error));}};
const askConfirm=(request:Confirmation)=>setConfirmation(request);
const confirmAction=async()=>{const request=confirmation;if(!request)return;try{await request.run();setConfirmation(null);}catch(error){toast(error instanceof Error?error.message:String(error));}};
const remove=async(entity:string,id:string)=>{const project=projects.find(item=>item.id===id);const version=data.versions.find(item=>item.id===id);const label=project?.name??data.modules.find(item=>item.id===id)?.name??version?.name??environments.find(item=>item.id===id)?.name??data.tables.find(item=>item.id===id)?.name??data.fields.find(item=>item.id===id)?.name??data.repositories.find(item=>item.id===id)?.name??'';const versionEnvironmentCount=version?environments.filter(item=>item.versionId===version.id).length:0;const impact=project?(locale==='zh'?`同时删除 ${project.versionCount} 个版本、${project.environmentCount} 个环境，以及所属范围和导入记录。`:`This also removes ${project.versionCount} versions, ${project.environmentCount} environments, scopes, and import history.`):version?(locale==='zh'?`该版本的字段登记与 SQL 导入记录会删除；绑定它的 ${versionEnvironmentCount} 个环境会保留，但变为未绑定版本。`:`Field registrations and SQL imports for this version will be deleted. Its ${versionEnvironmentCount} environments will remain but become unassigned.`):(locale==='zh'?'相关引用会一并清理。':'Related references will be cleaned up.');askConfirm({title:t.confirmDelete,description:`${label?`“${label}” · `:''}${impact} ${locale==='zh'?'此操作无法撤销。':'This cannot be undone.'}`,confirmLabel:t.remove,run:async()=>{await call('entity.delete',{entity,id});toast(t.deleted);}});};
const submitField=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget).entries());const table=data.tables.find(item=>item.name===String(values.tableName).trim().toLowerCase());if(!table){toast(locale==='zh'?'请选择已有数据表':'Choose an existing table');return;}try{await call('field.save',{...editing,...values,tableId:table.id,projectId:scopeProject,versionId:scopeVersion,environmentIds:scopeEnvs,nullable:values.nullable==='on'});close();toast(t.saved);}catch(error){toast(error instanceof Error?error.message:String(error));}};
const runImport=async()=>{try{const result=await call('import.sql',{name:importName,sql:importSql,sourceKind:importSourcePath||importGitCommit?'github':importFile?'upload':'paste',fileName:importFile||null,sourcePath:importSourcePath,gitCommit:importGitCommit,projectId:scopeProject,versionId:scopeVersion,environmentIds:scopeEnvs,moduleId:importModule||null});toast(result.duplicateBatch?String(result.batchCode):`${result.batchCode}  +${result.added}  =${result.duplicates}  !${result.conflicts}`);setImportName('');setImportSql('');setImportFile('');setImportSourcePath('');setImportGitCommit('');}catch(error){toast(error instanceof Error?error.message:String(error));}};
const readFiles=async(files:FileList|null)=>{if(!files?.length)return;const selected=Array.from(files);setImportFile(selected.map(file=>file.name).join(', '));setImportSql((await Promise.all(selected.map(async file=>`-- ${file.name}\n${await file.text()}`))).join('\n\n'));};
const reuseImport=(batch:ImportBatch)=>{setSelectedImport(null);setSelectedEnvironment(null);setView('imports');setScopeProject(batch.projectId);setScopeVersion(batch.versionId);setScopeEnvs((batch.environmentIds??'').split('|||').filter(Boolean));setImportModule(batch.moduleId??'');setImportName(locale==='zh'?`${batch.name} · 再次执行`:`${batch.name} · rerun`);setImportSql(batch.rawSql??'');setImportFile(batch.fileName??'');setImportSourcePath(batch.sourcePath??'');setImportGitCommit(batch.gitCommit??'');};
const nav:{view:View;label:string;icon:typeof Search}[]=[{view:'explorer',label:locale==='zh'?'查字段':'Find field',icon:Search},{view:'projects',label:t.projects,icon:GitBranch},{view:'imports',label:t.imports,icon:Import},{view:'settings',label:t.settings,icon:Settings}];

return <main className="min-h-svh bg-background text-foreground"><header className="sticky top-0 z-30 border-b bg-background/90 backdrop-blur-xl"><div className="mx-auto grid h-14 max-w-7xl grid-cols-[1fr_auto_1fr] items-center gap-4 px-4"><Button type="button" variant="ghost" className="h-auto w-fit gap-2 p-1" onClick={()=>go('explorer')} aria-label="Drifty"><span className="grid size-8 place-items-center rounded-lg bg-foreground text-xs font-semibold text-background">D</span><span className="hidden text-sm font-semibold tracking-tight sm:block">Drifty</span></Button><PrimaryNav view={view} nav={nav} go={go}/><div className="flex items-center justify-end gap-1"><LanguageSwitcher locale={locale} chooseLocale={chooseLocale}/><span className="hidden sm:inline-flex"><IconButton label={`${t.theme} · ${themeLabel}`} onClick={cycleTheme}>{theme==='dark'?<Moon/>:theme==='light'?<Sun/>:<Monitor/>}</IconButton></span><CreateMenu t={t} projects={projects} open={open} go={go}/></div></div></header>
{notice&&<div className="fixed left-1/2 top-18 z-50 flex -translate-x-1/2 items-center gap-2 rounded-full border bg-foreground px-4 py-2 text-xs text-background shadow-xl"><Check className="size-3.5"/>{notice}</div>}
<section className="mx-auto max-w-7xl px-4 py-6">
{view==='explorer'&&<ExplorerView query={query} setQuery={setQuery} totalFields={data.fieldTotal} projects={projects} environments={environments} versions={data.versions} locale={locale} onSelectField={(field,scopes)=>setSelectedField({field,scopes})}/>}
{view==='projects'&&<ProjectsWorkspace projects={projects} projectVersions={projectVersions} projectEnvs={projectEnvs} locale={locale} open={open} remove={remove} onSelect={project=>{setSelectedProject(project);setProjectTab('differences');}}/>}
{view==='imports'&&<ImportWorkspace data={data} projects={projects} scopeProject={scopeProject} scopeVersion={scopeVersion} scopeEnvs={scopeEnvs} importName={importName} importModule={importModule} importSql={importSql} importFile={importFile} importSourcePath={importSourcePath} importGitCommit={importGitCommit} busy={busy} locale={locale} t={t} chooseScopeProject={chooseScopeProject} setScopeVersion={setScopeVersion} setScopeEnvs={setScopeEnvs} setImportName={setImportName} setImportModule={setImportModule} setImportSql={setImportSql} setImportSourcePath={setImportSourcePath} setImportGitCommit={setImportGitCommit} readFiles={readFiles} runImport={runImport} projectVersions={projectVersions} projectEnvs={projectEnvs} call={call} toast={toast} askConfirm={askConfirm} onSelectImport={setSelectedImport} open={open}/>}
{view==='settings'&&<SettingsView data={data} t={t} open={open} remove={remove} call={call} toast={toast} askConfirm={askConfirm}/>}</section>
<Sheet open={Boolean(selectedField)} onOpenChange={open=>{if(!open)setSelectedField(null);}}><SheetContent>{selectedField&&<FieldDetail field={selectedField.field} projects={projects} environments={environments} versions={data.versions} scopes={selectedField.scopes} tables={data.tables} locale={locale} onEdit={()=>{const field=selectedField.field,scopes=selectedField.scopes;setSelectedField(null);open('field',{...field,__scopes:scopes} as unknown as Record<string,unknown>);}} onDelete={()=>{const field=selectedField.field;setSelectedField(null);void remove('field',field.id);}}/>}</SheetContent></Sheet>
<Sheet open={Boolean(selectedProject)} onOpenChange={open=>{if(!open){setSelectedProject(null);setSelectedEnvironment(null);}}}><SheetContent className="max-w-2xl">{selectedProject&&<ProjectDetail key={selectedProject.id} project={selectedProject} tab={projectTab} setTab={setProjectTab} data={data} environments={environments} locale={locale} open={open} remove={remove} onSelectEnvironment={setSelectedEnvironment} onSelectImport={setSelectedImport}/>}</SheetContent></Sheet>
<Sheet open={Boolean(selectedEnvironment)} onOpenChange={open=>{if(!open)setSelectedEnvironment(null);}}><SheetContent className="max-w-xl">{selectedEnvironment&&<EnvironmentDetail key={selectedEnvironment.id} environment={selectedEnvironment} locale={locale} onEdit={()=>{const environment=selectedEnvironment;setSelectedEnvironment(null);open('environment',environment as unknown as Record<string,unknown>);}} onSelectImport={setSelectedImport}/>}</SheetContent></Sheet>
<Sheet open={Boolean(selectedImport)} onOpenChange={open=>{if(!open)setSelectedImport(null);}}><SheetContent className="max-w-2xl">{selectedImport&&<ImportDetail key={selectedImport} importId={selectedImport} locale={locale} call={call} toast={toast} askConfirm={askConfirm} onReuse={reuseImport}/>}</SheetContent></Sheet>
<Dialog open={Boolean(modal)} onOpenChange={value=>{if(!value)close();}}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-lg"><DialogHeader><DialogTitle>{modal?modalTitle(modal,t,Boolean(editing.id)):''}</DialogTitle><DialogDescription className="sr-only">Drifty</DialogDescription></DialogHeader>
{modal==='project'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'project.save')}><Field label={t.name}><Input name="name" defaultValue={String(editing.name??'')} required/></Field><div className="grid grid-cols-2 gap-4"><Field label={t.code}><Input name="code" defaultValue={String(editing.code??'')}/></Field><Field label={t.kind}><SelectField name="kind" defaultValue={String(editing.kind??'project')}><option value="platform">{t.platform}</option><option value="project">{t.customerProject}</option></SelectField></Field></div><Field label={locale==='zh'?'项目图标':'Project icon'}><ProjectIconPicker defaultValue={String(editing.icon??(editing.kind==='platform'?'server':'package'))}/></Field><Field label={t.parentPlatform}><SelectField name="parentId" defaultValue={String(editing.parentId??'')}><option value="">—</option>{projects.filter(item=>item.kind==='platform'&&item.id!==editing.id).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</SelectField></Field><Field label={t.description}><Textarea name="description" defaultValue={String(editing.description??'')}/></Field><ModalActions busy={busy} t={t} onClose={close}/></form>}
{modal==='module'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'module.save')}><Field label={t.name}><Input name="name" defaultValue={String(editing.name??'')} required/></Field><Field label={t.code}><Input name="code" defaultValue={String(editing.code??'')}/></Field><Field label={t.description}><Textarea name="description" defaultValue={String(editing.description??'')}/></Field><ModalActions busy={busy} t={t} onClose={close}/></form>}
{modal==='version'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'version.save')}><Field label={t.targetProject}><SelectField name="projectId" defaultValue={String(editing.projectId??scopeProject)} required>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField></Field><div className="grid grid-cols-2 gap-4"><Field label={t.version}><Input name="name" defaultValue={String(editing.name??'')} placeholder="3.8.0" required/></Field><Field label={t.sourceVersion}><Input name="sourceVersion" defaultValue={String(editing.sourceVersion??'')}/></Field></div><div className="rounded-xl border p-3"><div className="mb-3 flex items-center gap-2 text-xs font-medium"><GitBranch className="size-3.5"/>{locale==='zh'?'Git 来源':'Git source'}</div><div className="space-y-3"><Field label={locale==='zh'?'仓库来源':'Repository'}><SelectField name="repositoryId" defaultValue={String(editing.repositoryId??'')}><option value="">{locale==='zh'?'暂不关联':'Not linked'}</option>{data.repositories.filter(source=>!source.projectId||source.projectId===String(editing.projectId??scopeProject)).map(source=><option key={source.id} value={source.id}>{source.name} · {source.repository}</option>)}</SelectField></Field><div className="grid grid-cols-2 gap-3"><Field label={locale==='zh'?'分支 / Tag':'Branch / Tag'}><Input name="gitRef" defaultValue={String(editing.gitRef??'')} placeholder="main"/></Field><Field label={locale==='zh'?'提交':'Commit'}><Input name="gitCommit" defaultValue={String(editing.gitCommit??'')} placeholder="a1b2c3d"/></Field></div></div></div><ModalActions busy={busy} t={t} onClose={close} onDelete={editing.id?()=>{void remove('version',String(editing.id));close();}:undefined}/></form>}
{modal==='environment'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'environment.save')}><Field label={t.targetProject}><SelectField name="projectId" value={scopeProject} onValueChange={setScopeProject} required>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField></Field><div className="grid grid-cols-2 gap-4"><Field label={t.name}><Input name="name" defaultValue={String(editing.name??'')} required/></Field><Field label={t.code}><Input name="code" defaultValue={String(editing.code??'')}/></Field></div><div className="grid grid-cols-2 gap-4"><Field label={t.version}><SelectField name="versionId" defaultValue={String(editing.versionId??'')}><option value="">—</option>{projectVersions(scopeProject).map(version=><option key={version.id} value={version.id}>{version.name}</option>)}</SelectField></Field><Field label={t.stage}><SelectField name="stage" defaultValue={String(editing.stage??'custom')}><option value="development">Dev</option><option value="testing">Test</option><option value="production">Prod</option><option value="custom">Custom</option></SelectField></Field></div><Field label={t.sort}><Input type="number" name="sortOrder" defaultValue={String(editing.sortOrder??10)}/></Field><ModalActions busy={busy} t={t} onClose={close} onDelete={editing.id?()=>{void remove('environment',String(editing.id));close();}:undefined}/></form>}
{modal==='table'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'table.save')}><Field label={t.tableName}><Input name="name" defaultValue={String(editing.name??'')} placeholder="customer" required/></Field><div className="grid grid-cols-2 gap-4"><Field label={t.code}><Input name="code" defaultValue={String(editing.code??'')}/></Field><Field label={t.ownerModule}><SelectField name="moduleId" defaultValue={String(editing.moduleId??'')}><option value="">{t.unknown}</option>{data.modules.map(module=><option key={module.id} value={module.id}>{module.name}</option>)}</SelectField></Field></div><Field label={t.tableComment}><Input name="comment" defaultValue={String(editing.comment??'')}/></Field><ModalActions busy={busy} t={t} onClose={close}/></form>}
{modal==='field'&&<form className="space-y-4" onSubmit={submitField}><Field label={t.tableName}><SearchSelect name="tableName" defaultValue={String(editing.tableName??'')} placeholder={t.tableName} searchLabel={t.search} emptyLabel={t.noData} options={data.tables.map(table=>({value:table.name,label:table.name,meta:table.comment}))}/></Field><div className="grid grid-cols-2 gap-4"><Field label={t.fieldName}><Input name="name" defaultValue={String(editing.name??'')} required/></Field><Field label={t.dataType}><Input name="dataType" defaultValue={String(editing.dataType??'')} placeholder="varchar(50)" required/></Field></div><Field label={t.comment}><Input name="comment" defaultValue={String(editing.comment??'')}/></Field><div className="grid grid-cols-2 gap-4"><Field label={t.defaultValue}><Input name="defaultValue" defaultValue={String(editing.defaultValue??'')}/></Field><label className="grid gap-2 text-xs font-medium"><span>{t.nullable}</span><span className="flex h-9 items-center"><Switch name="nullable" value="on" defaultChecked={editing.nullable===undefined||Boolean(editing.nullable)} aria-label={t.nullable}/></span></label></div><div className="grid grid-cols-2 gap-4"><Field label={t.targetProject}><SelectField value={scopeProject} onValueChange={chooseScopeProject}>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField></Field><Field label={t.targetVersion}><SelectField value={scopeVersion} onValueChange={setScopeVersion}>{projectVersions(scopeProject).map(version=><option key={version.id} value={version.id}>{version.name}</option>)}</SelectField></Field></div><ScopePicker envs={projectEnvs(scopeProject)} selected={scopeEnvs} onChange={setScopeEnvs} t={t}/><ModalActions busy={busy} t={t} onClose={close}/></form>}
{modal==='repository'&&<form className="space-y-4" onSubmit={event=>submitSimple(event,'repository.save')}><Field label={t.name}><Input name="name" defaultValue={String(editing.name??'')} required/></Field><Field label={t.repository}><Input name="repository" defaultValue={String(editing.repository??'')} placeholder="owner/repository" required/></Field><div className="grid grid-cols-2 gap-4"><Field label={t.branch}><Input name="branch" defaultValue={String(editing.branch??'main')}/></Field><Field label={t.targetProject}><SelectField name="projectId" defaultValue={String(editing.projectId??'')}><option value="">—</option>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField></Field></div><Field label={t.pathPattern}><Input name="pathPattern" defaultValue={String(editing.pathPattern??'sql/**/*.sql')}/></Field><ModalActions busy={busy} t={t} onClose={close}/></form>}
</DialogContent></Dialog><AlertDialog open={Boolean(confirmation)} onOpenChange={open=>{if(!open&&!busy)setConfirmation(null);}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{confirmation?.title}</AlertDialogTitle><AlertDialogDescription>{confirmation?.description}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>{t.cancel}</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={event=>{event.preventDefault();void confirmAction();}}>{busy?'…':confirmation?.confirmLabel}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></main>;
}

function ExplorerView({query,setQuery,totalFields,projects,environments,versions,locale,onSelectField}:{query:string;setQuery:(value:string)=>void;totalFields:number;projects:Project[];environments:Environment[];versions:Version[];locale:'zh'|'en';onSelectField:(field:FieldItem,scopes:Scope[])=>void}){
  const [projectId,setProjectId]=useState('');
  const [versionId,setVersionId]=useState('');
  const [environmentId,setEnvironmentId]=useState('');
  const [fields,setFields]=useState<FieldItem[]>([]);
  const [scopes,setScopes]=useState<Scope[]>([]);
  const [resultTotal,setResultTotal]=useState(0);
  const [resolvedKey,setResolvedKey]=useState('');
  const availableVersions=versions.filter(item=>!projectId||item.projectId===projectId);
  const availableEnvironments=environments.filter(item=>(!projectId||item.projectId===projectId)&&(!versionId||item.versionId===versionId));
  const chooseProject=(id:string)=>{setProjectId(id);setVersionId('');setEnvironmentId('');};
  const chooseVersion=(id:string)=>{setVersionId(id);setEnvironmentId('');};
  const scopeLabel=[projects.find(item=>item.id===projectId)?.name,versions.find(item=>item.id===versionId)?.name,environments.find(item=>item.id===environmentId)?.name].filter(Boolean).join(' · ');
  const searchKey=`${query.trim()}|${projectId}|${versionId}|${environmentId}`;
  const searching=Boolean(query.trim())&&resolvedKey!==searchKey;
  useEffect(()=>{const normalized=query.trim();if(!normalized)return;const controller=new AbortController();const timer=window.setTimeout(async()=>{const params=new URLSearchParams({mode:'search',q:normalized});if(projectId)params.set('projectId',projectId);if(versionId)params.set('versionId',versionId);if(environmentId)params.set('environmentId',environmentId);try{const response=await fetch(`/api/catalog?${params}`,{signal:controller.signal});if(!response.ok)throw new Error('search');const result=await response.json() as {fields:FieldItem[];scopes:Scope[];total:number};setFields(result.fields);setScopes(result.scopes);setResultTotal(result.total);setResolvedKey(searchKey);}catch(error){if((error as Error).name!=='AbortError'){setFields([]);setScopes([]);setResultTotal(0);setResolvedKey(searchKey);}}},180);return()=>{window.clearTimeout(timer);controller.abort();};},[query,projectId,versionId,environmentId,searchKey]);
  return <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_280px]">
    <Card className="gap-0 overflow-hidden py-0">
      <div className="border-b p-4">
        <div className="relative"><Search className="pointer-events-none absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input autoFocus value={query} onChange={event=>setQuery(event.target.value)} className="h-11 rounded-xl border-0 bg-muted/70 pl-10 pr-4 text-sm shadow-none focus-visible:ring-1" placeholder={locale==='zh'?'输入 customer.level、字段编码或说明':'Search customer.level, code, or description'}/></div>
        <div className="mt-3 grid gap-2 sm:grid-cols-3">
          <SelectField value={projectId} onValueChange={chooseProject} aria-label={locale==='zh'?'项目':'Project'}><option value="">{locale==='zh'?'所有项目':'All projects'}</option>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField>
          <SelectField value={versionId} onValueChange={chooseVersion} disabled={!projectId} aria-label={locale==='zh'?'版本':'Version'}><option value="">{locale==='zh'?'所有版本':'All versions'}</option>{availableVersions.map(version=><option key={version.id} value={version.id}>{version.name}</option>)}</SelectField>
          <SelectField value={environmentId} onValueChange={setEnvironmentId} disabled={!projectId} aria-label={locale==='zh'?'环境':'Environment'}><option value="">{locale==='zh'?'所有环境':'All environments'}</option>{availableEnvironments.map(env=><option key={env.id} value={env.id}>{env.name}</option>)}</SelectField>
        </div>
      </div>
      <div className="min-h-[420px]">
        {!query.trim()?<div className="grid min-h-[420px] place-items-center px-6 text-center"><div className="max-w-sm"><span className="mx-auto grid size-10 place-items-center rounded-xl bg-muted"><Search className="size-4 text-muted-foreground"/></span><p className="mt-4 text-sm font-medium">{locale==='zh'?'从一个字段开始':'Start with a field'}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{locale==='zh'?`按字段名、表名、编码或说明搜索；共 ${totalFields} 个字段，只有搜索后才加载结果。`:`Search by field, table, code, or description. ${totalFields} fields stay hidden until needed.`}</p></div></div>:searching?<div className="grid min-h-[420px] place-items-center text-xs text-muted-foreground">{locale==='zh'?'正在查找…':'Searching…'}</div>:fields.length?<div className="divide-y"><div className="flex items-center justify-between px-4 py-2 text-[10px] text-muted-foreground"><span>{locale==='zh'?`找到 ${resultTotal} 个字段`:`${resultTotal} fields found`}</span>{resultTotal>80&&<span>{locale==='zh'?'显示最相关的 80 条':'Top 80 results'}</span>}</div>{fields.map(field=>{const fieldScopes=scopes.filter(scope=>scope.fieldId===field.id);const projectCount=new Set(fieldScopes.map(scope=>scope.projectId)).size;const environmentCount=new Set(fieldScopes.map(scope=>scope.environmentId)).size;const targetChosen=Boolean(projectId||versionId||environmentId);const targetPresent=fieldScopes.some(scope=>(!projectId||scope.projectId===projectId)&&(!versionId||scope.versionId===versionId)&&(!environmentId||scope.environmentId===environmentId));return <button key={field.id} type="button" onClick={()=>onSelectField(field,fieldScopes)} className="grid w-full grid-cols-[minmax(0,1fr)_auto] items-center gap-4 px-4 py-3.5 text-left transition-colors hover:bg-muted/50 focus-visible:bg-muted/50 focus-visible:outline-none"><span className="min-w-0"><span className="flex items-center gap-2"><code className="truncate text-xs font-semibold">{field.tableName}.{field.name}</code><Badge variant="secondary" className="shrink-0 text-[10px]">{field.code}</Badge></span><span className="mt-1 block truncate text-[11px] text-muted-foreground">{field.comment||field.dataType}{field.comment?` · ${field.dataType}`:''}</span></span><span className="flex items-center gap-3 text-[11px] text-muted-foreground">{targetChosen?<Badge variant={targetPresent?"secondary":"outline"} className={targetPresent?"text-emerald-700 dark:text-emerald-300":""}>{targetPresent?<CheckCircle2 className="size-3"/>:<XCircle className="size-3"/>}{targetPresent?(locale==="zh"?"存在":"Present"):(locale==="zh"?"未登记":"Missing")}</Badge>:<><span>{locale==="zh"?projectCount+" 个项目":projectCount+" projects"}</span><span>{locale==="zh"?environmentCount+" 个环境":environmentCount+" envs"}</span></>}<ArrowRight className="size-3.5"/></span></button>})}</div>:<div className="grid min-h-[420px] place-items-center px-6 text-center text-xs text-muted-foreground">{locale==='zh'?'没有找到符合当前范围的字段':'No field matches this scope'}</div>}
      </div>
    </Card>
    <aside className="space-y-3">
      <Card className="gap-3 py-4"><CardContent className="space-y-3 px-4"><div className="flex items-center gap-2 text-xs font-medium"><SlidersHorizontal className="size-3.5"/>{locale==='zh'?'当前判断范围':'Current scope'}</div><p className="text-xs leading-5 text-muted-foreground">{scopeLabel||(locale==='zh'?'全部项目、版本和环境':'All projects, versions, and environments')}</p>{scopeLabel&&<Button type="button" variant="ghost" size="sm" className="h-7 px-0 text-xs" onClick={()=>{setProjectId('');setVersionId('');setEnvironmentId('');}}>{locale==='zh'?'清除范围':'Clear scope'}</Button>}</CardContent></Card>
      <Card className="gap-3 py-4"><CardContent className="space-y-3 px-4"><div className="flex items-center gap-2 text-xs font-medium"><Info className="size-3.5"/>{locale==='zh'?'怎么看':'How to read'}</div><p className="text-[11px] leading-5 text-muted-foreground">{locale==='zh'?'点击字段后，会按项目和版本展开所有环境。勾表示存在，短横线表示未登记。':'Open a field to see every environment by project and version. Check means present; dash means not recorded.'}</p></CardContent></Card>
    </aside>
  </div>;
}

function FieldDetail({field,projects,environments,versions,scopes,tables,locale,onEdit,onDelete}:{field:FieldItem;projects:Project[];environments:Environment[];versions:Version[];scopes:Scope[];tables:TableItem[];locale:'zh'|'en';onEdit:()=>void;onDelete:()=>void}){
  const table=tables.find(item=>item.id===field.tableId);
  const fieldScopes=scopes.filter(scope=>scope.fieldId===field.id);
  return <><SheetHeader><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><SheetTitle className="font-mono">{field.tableName}.{field.name}</SheetTitle><SheetDescription>{field.comment||(locale==='zh'?'暂无字段说明':'No field description')}</SheetDescription></div><EntityMenu t={locale==='zh'?words.zh:words.en} onEdit={onEdit} onDelete={onDelete}/></div></SheetHeader><div className="flex-1 overflow-y-auto p-6">
    <div className="grid grid-cols-2 gap-px overflow-hidden rounded-xl border bg-border sm:grid-cols-3">{[
      [locale==='zh'?'字段编码':'Field code',field.code],[locale==='zh'?'数据类型':'Data type',field.dataType],[locale==='zh'?'允许空值':'Nullable',field.nullable?(locale==='zh'?'是':'Yes'):(locale==='zh'?'否':'No')],
      [locale==='zh'?'默认值':'Default',field.defaultValue??'—'],[locale==='zh'?'所属模块':'Module',field.moduleName??(locale==='zh'?'未分类':'Unclassified')],[locale==='zh'?'数据来源':'Source',field.sourceKind==='upload'?(locale==='zh'?'上传':'Upload'):field.sourceKind==='paste'?(locale==='zh'?'粘贴':'Paste'):field.sourceKind==='manual'?(locale==='zh'?'手动':'Manual'):field.sourceKind],
    ].map(([label,value])=><div key={label} className="bg-background p-3"><span className="block text-[10px] text-muted-foreground">{label}</span><span className="mt-1 block truncate text-xs">{value}</span></div>)}</div>
    <div className="mt-5 rounded-xl border p-4"><span className="text-[10px] text-muted-foreground">{locale==='zh'?'表说明':'Table description'}</span><p className="mt-1 text-xs leading-5">{table?.comment||(locale==='zh'?'暂无表说明':'No table description')}</p></div>
    <div className="mt-6 flex items-center justify-between"><span className="text-xs font-semibold">{locale==='zh'?'存在性':'Presence'}</span><span className="flex items-center gap-3 text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><CheckCircle2 className="size-3 text-emerald-600"/>{locale==='zh'?'存在':'Present'}</span><span className="flex items-center gap-1"><XCircle className="size-3"/>{locale==='zh'?'未登记':'Missing'}</span></span></div>
    <div className="mt-3 space-y-3">{projects.map(project=>{const projectVersions=versions.filter(version=>version.projectId===project.id);if(!projectVersions.length)return null;return <div key={project.id} className="rounded-xl border"><div className="flex items-center gap-2 border-b px-4 py-3"><span className={`size-2 rounded-full ${project.kind==='platform'?'bg-emerald-500':'bg-foreground/30'}`}/><strong className="text-xs">{project.name}</strong><span className="ml-auto text-[10px] text-muted-foreground">{project.code}</span></div><div className="divide-y">{projectVersions.map(version=>{const envs=environments.filter(env=>env.projectId===project.id&&(!env.versionId||env.versionId===version.id));return <div key={version.id} className="grid gap-3 px-4 py-3 sm:grid-cols-[90px_1fr]"><code className="text-[11px] text-muted-foreground">{version.name}</code><div className="flex flex-wrap gap-2">{envs.map(env=>{const present=fieldScopes.some(scope=>scope.versionId===version.id&&scope.environmentId===env.id);return <span key={env.id} className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] ${present?'bg-emerald-50 text-emerald-800 dark:bg-emerald-950/30 dark:text-emerald-300':'text-muted-foreground'}`}>{present?<CheckCircle2 className="size-3"/>:<XCircle className="size-3"/>}{env.name}</span>})}{!envs.length&&<span className="text-[10px] text-muted-foreground">{locale==='zh'?'暂无环境':'No environments'}</span>}</div></div>})}</div></div>})}</div>
  </div></>;
}

function ProjectsWorkspace({projects,projectVersions,projectEnvs,locale,open,remove,onSelect}:{projects:Project[];projectVersions:(id:string)=>Version[];projectEnvs:(id:string)=>Environment[];locale:'zh'|'en';open:(kind:Exclude<ModalKind,null>,record?:Record<string,unknown>)=>void;remove:(entity:string,id:string)=>Promise<void>;onSelect:(project:Project)=>void}){
  const [filter,setFilter]=useState('');
  const visible=projects.filter(project=>`${project.name} ${project.code} ${project.description}`.toLowerCase().includes(filter.trim().toLowerCase()));
  return <div className="space-y-3"><div className="flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"/><Input value={filter} onChange={event=>setFilter(event.target.value)} className="h-9 pl-9 text-xs" placeholder={locale==='zh'?'搜索项目':'Search projects'}/></div><Button type="button" size="sm" onClick={()=>open('project')}><Plus/>{locale==='zh'?'项目':'Project'}</Button></div><Card className="gap-0 overflow-hidden py-0"><CardContent className="divide-y p-0">{visible.map(project=>{const versions=projectVersions(project.id);const envs=projectEnvs(project.id);return <div key={project.id} className="group grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3 px-3 py-3 hover:bg-muted/35"><button type="button" onClick={()=>onSelect(project)} className="grid min-w-0 gap-3 rounded-lg p-1 text-left outline-none focus-visible:ring-2 sm:grid-cols-[minmax(170px,1fr)_minmax(120px,.7fr)_minmax(220px,1.4fr)] sm:items-center"><span className="flex min-w-0 items-center gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground"><ProjectIcon name={project.icon}/></span><span className="min-w-0"><strong className="block truncate text-xs">{project.name}</strong><span className="mt-0.5 block truncate text-[10px] text-muted-foreground">{project.description||project.code}</span></span></span><span className="text-[11px] text-muted-foreground">{locale==='zh'?`${versions.length} 个版本`:`${versions.length} versions`}<strong className="ml-2 font-mono font-medium text-foreground">{versions[0]?.name??'—'}</strong></span><span className="flex flex-wrap gap-1.5">{envs.map(env=><span key={env.id} className="rounded-full border bg-background px-2 py-1 text-[10px] text-muted-foreground">{env.name} · {env.fieldCount} {locale==='zh'?'字段':'fields'}</span>)}</span></button><div className="flex items-center"><ArrowRight className="mr-1 size-3.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100"/><EntityMenu t={locale==='zh'?words.zh:words.en} onEdit={()=>open('project',project as unknown as Record<string,unknown>)} onDelete={()=>void remove('project',project.id)}/></div></div>})}{!visible.length&&<Empty text={locale==='zh'?'没有找到项目':'No projects found'}/>}</CardContent></Card></div>;
}

function ProjectDetail({project,tab,setTab,data,environments,locale,open,remove,onSelectEnvironment,onSelectImport}:{project:Project;tab:'differences'|'history'|'environments';setTab:(tab:'differences'|'history'|'environments')=>void;data:CatalogData;environments:Environment[];locale:'zh'|'en';open:(kind:Exclude<ModalKind,null>,record?:Record<string,unknown>)=>void;remove:(entity:string,id:string)=>Promise<void>;onSelectEnvironment:(environment:Environment)=>void;onSelectImport:(id:string)=>void}){
  const versions=data.versions.filter(version=>version.projectId===project.id);
  const envs=environments.filter(env=>env.projectId===project.id);
  const [insight,setInsight]=useState<ProjectInsight>({differences:[],imports:[]});
  const [loading,setLoading]=useState(true);
  useEffect(()=>{const controller=new AbortController();fetch(`/api/catalog?mode=project&projectId=${encodeURIComponent(project.id)}`,{signal:controller.signal}).then(response=>{if(!response.ok)throw new Error('project');return response.json() as Promise<ProjectInsight>;}).then(setInsight).catch(error=>{if((error as Error).name!=='AbortError')setInsight({differences:[],imports:[]});}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[project.id]);
  const differences=insight.differences;
  const imports=insight.imports;
  return <><SheetHeader><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-lg bg-muted text-muted-foreground"><ProjectIcon name={project.icon}/></span><div className="min-w-0"><SheetTitle>{project.name}</SheetTitle><SheetDescription>{project.description||project.code}</SheetDescription></div><Button type="button" variant="ghost" size="sm" className="ml-auto" onClick={()=>open('project',project as unknown as Record<string,unknown>)}><Pencil/>{locale==='zh'?'编辑':'Edit'}</Button></div></SheetHeader>
    <div className="border-b px-6 py-4"><div className="grid grid-cols-3 gap-2">{[[versions.length,locale==='zh'?'版本':'Versions'],[envs.length,locale==='zh'?'环境':'Environments'],[project.fieldCount,locale==='zh'?'已登记字段':'Registered fields']].map(([value,label])=><div key={String(label)}><strong className="block text-lg tabular-nums">{value}</strong><span className="text-[10px] text-muted-foreground">{label}</span></div>)}</div><Tabs value={tab} onValueChange={value=>setTab(value as typeof tab)} className="mt-4"><TabsList className="w-full"><TabsTrigger value="differences" className="flex-1">{locale==='zh'?'字段差异':'Differences'}<Badge variant="secondary">{differences.length}</Badge></TabsTrigger><TabsTrigger value="history" className="flex-1">{locale==='zh'?'SQL 记录':'SQL history'}<Badge variant="secondary">{imports.length}</Badge></TabsTrigger><TabsTrigger value="environments" className="flex-1">{locale==='zh'?'版本与环境':'Versions & envs'}</TabsTrigger></TabsList></Tabs></div>
    <div className="flex-1 overflow-y-auto p-6">{loading&&tab!=='environments'?<div className="grid min-h-52 place-items-center text-xs text-muted-foreground">{locale==='zh'?'正在整理项目数据…':'Loading project details…'}</div>:tab==='differences'&&(differences.length?<div className="space-y-2">{differences.map(item=>{const missing=(item.missingEnvironments??'').split('|||').filter(Boolean);return <div key={`${item.id}-${item.versionId}`} className="rounded-xl border p-3"><div className="flex items-center gap-2"><code className="min-w-0 flex-1 truncate text-xs font-semibold">{item.tableName}.{item.name}</code><Badge variant="outline">{item.versionName}</Badge></div><p className="mt-1 text-[10px] text-muted-foreground">{item.comment||item.dataType}</p><div className="mt-3 flex flex-wrap items-center gap-1.5"><span className="mr-1 text-[10px] text-muted-foreground">{locale==='zh'?`已存在 ${item.presentCount}/${item.totalCount}`:`Present ${item.presentCount}/${item.totalCount}`}</span>{missing.map(name=><span key={name} className="rounded-full bg-amber-50 px-2 py-1 text-[10px] text-amber-800 dark:bg-amber-950/30 dark:text-amber-300">{locale==='zh'?'缺少 ':'Missing '}{name}</span>)}</div></div>})}</div>:<Empty text={locale==='zh'?'当前没有发现环境间字段差异':'No environment differences found'}/>)}
      {!loading&&tab==='history'&&(imports.length?<div className="space-y-2">{imports.map(batch=><button type="button" key={batch.id} onClick={()=>onSelectImport(batch.id)} className="w-full rounded-xl border p-3 text-left transition-colors hover:bg-muted/40"><div className="flex items-center gap-2"><FileCode2 className="size-3.5 text-muted-foreground"/><strong className="min-w-0 flex-1 truncate text-xs">{batch.name}</strong><Badge variant={batch.status==='active'?'secondary':'outline'}>{batch.versionName}</Badge><ArrowRight className="size-3.5 text-muted-foreground"/></div><div className="mt-1 truncate text-[10px] text-muted-foreground">{batch.code}{batch.moduleName?` · ${batch.moduleName}`:''}{batch.environmentNames?` · ${batch.environmentNames}`:''}</div><div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-[10px] text-muted-foreground"><span>{new Date(batch.createdAt).toLocaleString(locale==='zh'?'zh-CN':'en')}</span><span>{locale==='zh'?`新增 ${batch.addedCount}`:`Added ${batch.addedCount}`}</span><span>{locale==='zh'?`重复 ${batch.duplicateCount}`:`Duplicate ${batch.duplicateCount}`}</span><span>{locale==='zh'?`冲突 ${batch.conflictCount}`:`Conflict ${batch.conflictCount}`}</span></div></button>)}</div>:<Empty text={locale==='zh'?'还没有 SQL 导入记录':'No SQL import history yet'}/>)}
      {tab==='environments'&&<div className="space-y-6">
        <section><div className="mb-2 flex items-center"><div><strong className="block text-xs">{locale==='zh'?'版本':'Versions'}</strong><span className="text-[10px] text-muted-foreground">{locale==='zh'?'版本可以关联 Git 分支、Tag 或提交':'Versions can track a Git branch, tag, or commit'}</span></div><span className="ml-auto"><IconButton label={locale==='zh'?'新增版本':'New version'} onClick={()=>open('version',{projectId:project.id})}><Plus/></IconButton></span></div><div className="divide-y rounded-xl border">{versions.map(version=>{const linkedEnvironments=envs.filter(env=>env.versionId===version.id).length;return <div key={version.id} className="flex items-center gap-3 px-3 py-3"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-muted"><Layers3 className="size-3.5"/></span><span className="min-w-0 flex-1"><strong className="block truncate font-mono text-xs">{version.name}</strong><span className="block truncate text-[10px] text-muted-foreground">{version.repository?<><GitBranch className="mr-1 inline size-3"/>{version.repository}{version.gitRef?`@${version.gitRef}`:''}{version.gitCommit?` · ${version.gitCommit.slice(0,8)}`:''}</>:(version.sourceVersion?(locale==='zh'?`来源 ${version.sourceVersion}`:`From ${version.sourceVersion}`):(locale==='zh'?'独立版本':'Independent version'))} · {linkedEnvironments} {locale==='zh'?'个环境':'environments'}</span></span><EntityMenu t={locale==='zh'?words.zh:words.en} onEdit={()=>open('version',version as unknown as Record<string,unknown>)} onDelete={()=>void remove('version',version.id)}/></div>})}{!versions.length&&<Empty text={locale==='zh'?'还没有版本':'No versions yet'}/>}</div></section>
        <section><div className="mb-2 flex items-center"><div><strong className="block text-xs">{locale==='zh'?'环境':'Environments'}</strong><span className="text-[10px] text-muted-foreground">{locale==='zh'?'点击查看详情，编辑与删除使用右侧菜单':'Open details; use the menu to edit or delete'}</span></div><span className="ml-auto"><IconButton label={locale==='zh'?'新增环境':'New environment'} onClick={()=>open('environment',{projectId:project.id})}><Plus/></IconButton></span></div><div className="space-y-2">{envs.map(env=><div key={env.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center rounded-xl border"><button type="button" onClick={()=>onSelectEnvironment(env)} className="flex min-w-0 items-center gap-3 p-3 text-left hover:bg-muted/50"><span className={`size-2 rounded-full ${env.stage==='production'?'bg-emerald-500':env.stage==='testing'?'bg-amber-500':'bg-sky-500'}`}/><span className="min-w-0 flex-1"><strong className="block text-xs">{env.name}</strong><span className="text-[10px] text-muted-foreground">{env.versionName??(locale==='zh'?'未绑定版本':'No version')}</span></span><span className="text-[11px] text-muted-foreground">{env.fieldCount} {locale==='zh'?'个字段':'fields'}</span><ArrowRight className="size-3.5 text-muted-foreground"/></button><div className="pr-1"><EntityMenu t={locale==='zh'?words.zh:words.en} onEdit={()=>open('environment',env as unknown as Record<string,unknown>)} onDelete={()=>void remove('environment',env.id)}/></div></div>)}{!envs.length&&<Empty text={locale==='zh'?'还没有环境':'No environments yet'}/>}</div></section>
      </div>}
    </div></>;
}




function EnvironmentDetail({environment,locale,onEdit,onSelectImport}:{environment:Environment;locale:'zh'|'en';onEdit:()=>void;onSelectImport:(id:string)=>void}){
  const [insight,setInsight]=useState<EnvironmentInsight|null>(null);
  useEffect(()=>{const controller=new AbortController();fetch(`/api/catalog?mode=environment&environmentId=${encodeURIComponent(environment.id)}`,{signal:controller.signal}).then(response=>{if(!response.ok)throw new Error('environment');return response.json() as Promise<EnvironmentInsight>;}).then(setInsight).catch(()=>{});return()=>controller.abort();},[environment.id]);
  const expected=number(insight?.coverage?.expectedCount),present=number(insight?.coverage?.presentCount),missing=Math.max(0,expected-present);
  const stageLabel=environment.stage==='production'?(locale==='zh'?'正式':'Production'):environment.stage==='testing'?(locale==='zh'?'测试':'Testing'):environment.stage==='development'?(locale==='zh'?'开发':'Development'):(locale==='zh'?'自定义':'Custom');
  return <><SheetHeader><div className="flex items-center gap-3"><span className={`size-2 rounded-full ${environment.stage==='production'?'bg-emerald-500':environment.stage==='testing'?'bg-amber-500':'bg-sky-500'}`}/><div className="min-w-0"><SheetTitle>{environment.name}</SheetTitle><SheetDescription>{environment.projectName} · {environment.versionName??(locale==='zh'?'未绑定版本':'No version')}</SheetDescription></div><Button type="button" variant="ghost" size="sm" className="ml-auto" onClick={onEdit}><Pencil/>{locale==='zh'?'编辑':'Edit'}</Button></div></SheetHeader><div className="border-b px-6 py-4"><div className="grid grid-cols-3 gap-2"><div><strong className="block text-lg tabular-nums">{present}</strong><span className="text-[10px] text-muted-foreground">{locale==='zh'?'已有字段':'Present fields'}</span></div><div><strong className="block text-lg tabular-nums">{expected}</strong><span className="text-[10px] text-muted-foreground">{locale==='zh'?'预期字段':'Expected fields'}</span></div><div><strong className={`block text-lg tabular-nums ${missing?'text-amber-600':''}`}>{missing}</strong><span className="text-[10px] text-muted-foreground">{locale==='zh'?'缺少字段':'Missing fields'}</span></div></div><div className="mt-3 flex gap-1.5"><Badge variant="secondary">{stageLabel}</Badge><Badge variant="outline">{environment.code}</Badge></div></div><div className="flex-1 space-y-6 overflow-y-auto p-6">{!insight?<Empty text={locale==='zh'?'正在整理环境数据…':'Loading environment details…'}/>:<><section><div className="mb-2 flex items-center gap-2"><Database className="size-3.5"/><strong className="text-xs">{locale==='zh'?'结构状态':'Schema status'}</strong><Badge variant={missing?'secondary':'outline'} className="ml-auto">{missing?`${missing}`:(locale==='zh'?'已对齐':'Aligned')}</Badge></div>{insight.missing.length?<div className="divide-y rounded-xl border">{insight.missing.map(field=><div key={field.id} className="px-3 py-2.5"><code className="block truncate text-[11px] font-semibold">{field.tableName}.{field.name}</code><span className="text-[10px] text-muted-foreground">{field.comment||field.dataType}</span></div>)}</div>:<div className="flex items-center gap-2 rounded-xl border p-4 text-xs text-muted-foreground"><CheckCircle2 className="size-4 text-emerald-500"/>{locale==='zh'?'当前环境已包含全部预期字段':'This environment contains every expected field'}</div>}</section><section><div className="mb-2 flex items-center gap-2"><History className="size-3.5"/><strong className="text-xs">{locale==='zh'?'SQL 记录':'SQL history'}</strong><Badge variant="secondary" className="ml-auto">{insight.imports.length}</Badge></div>{insight.imports.length?<div className="space-y-2">{insight.imports.map(batch=><button key={batch.id} type="button" onClick={()=>onSelectImport(batch.id)} className="flex w-full items-center gap-3 rounded-xl border p-3 text-left hover:bg-muted/50"><FileCode2 className="size-3.5 text-muted-foreground"/><span className="min-w-0 flex-1"><strong className="block truncate text-xs">{batch.name}</strong><span className="text-[10px] text-muted-foreground">{batch.versionName} · {new Date(batch.createdAt).toLocaleString(locale==='zh'?'zh-CN':'en')}</span></span><ArrowRight className="size-3.5 text-muted-foreground"/></button>)}</div>:<Empty text={locale==='zh'?'这个环境还没有 SQL 记录':'No SQL history for this environment'}/>}</section></>}</div></>;
}

function ImportDetail({importId,locale,call,toast,askConfirm,onReuse}:{importId:string;locale:'zh'|'en';call:(action:string,payload?:Record<string,unknown>)=>Promise<Record<string,unknown>>;toast:(message:string)=>void;askConfirm:(request:Confirmation)=>void;onReuse:(batch:ImportBatch)=>void}){
  const [insight,setInsight]=useState<ImportInsight|null>(null);const [renaming,setRenaming]=useState(false);const [name,setName]=useState('');
  const loadDetail=useCallback(()=>fetch(`/api/catalog?mode=import&importId=${encodeURIComponent(importId)}`).then(response=>{if(!response.ok)throw new Error('import');return response.json() as Promise<ImportInsight>;}).then(result=>{setInsight(result);setName(result.batch.name);}),[importId]);
  useEffect(()=>{void loadDetail();},[loadDetail]);
  if(!insight)return <Empty text={locale==='zh'?'正在读取 SQL 记录…':'Loading SQL record…'}/>;
  const {batch,items}=insight;
  const rename=async()=>{if(!name.trim())return;try{await call('import.rename',{id:batch.id,name:name.trim()});setInsight({...insight,batch:{...batch,name:name.trim()}});setRenaming(false);toast(locale==='zh'?'名称已更新':'Name updated');}catch(error){toast(error instanceof Error?error.message:String(error));}};
  const copySql=async()=>{try{await navigator.clipboard.writeText(batch.rawSql??'');toast(locale==='zh'?'SQL 已复制':'SQL copied');}catch{toast(locale==='zh'?'复制失败':'Copy failed');}};
  return <><SheetHeader><div className="flex items-start gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted"><FileCode2 className="size-4"/></span><div className="min-w-0 flex-1">{renaming?<div className="flex gap-2"><Input value={name} onChange={event=>setName(event.target.value)} autoFocus/><Button size="sm" onClick={()=>void rename()}>{locale==='zh'?'保存':'Save'}</Button></div>:<><SheetTitle className="truncate">{batch.name}</SheetTitle><SheetDescription>{batch.code} · {batch.projectName} · {batch.versionName}</SheetDescription></>}</div>{!renaming&&<IconButton label={locale==='zh'?'编辑名称':'Rename'} onClick={()=>setRenaming(true)}><Pencil/></IconButton>}</div></SheetHeader><div className="border-b px-6 py-4"><div className="flex flex-wrap gap-1.5"><Badge variant="secondary">{locale==='zh'?`新增 ${batch.addedCount}`:`Added ${batch.addedCount}`}</Badge><Badge variant="outline">{locale==='zh'?`重复 ${batch.duplicateCount}`:`Duplicate ${batch.duplicateCount}`}</Badge><Badge variant={batch.conflictCount?'destructive':'outline'}>{locale==='zh'?`冲突 ${batch.conflictCount}`:`Conflict ${batch.conflictCount}`}</Badge><Badge variant="outline">{batch.status==='active'?(locale==='zh'?'有效':'Active'):(locale==='zh'?'已撤销':'Reverted')}</Badge></div><div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-[10px] text-muted-foreground"><span>{new Date(batch.createdAt).toLocaleString(locale==='zh'?'zh-CN':'en')}</span>{batch.moduleName&&<span>{batch.moduleName}</span>}{batch.environmentNames&&<span>{batch.environmentNames.split('|||').join(' · ')}</span>}{batch.sourcePath&&<span>{batch.sourcePath}</span>}{batch.gitCommit&&<span><GitCommitHorizontal className="mr-1 inline size-3"/>{batch.gitCommit.slice(0,10)}</span>}</div><div className="mt-4 flex gap-2"><Button type="button" variant="outline" size="sm" onClick={()=>void copySql()}><Copy/>{locale==='zh'?'复制 SQL':'Copy SQL'}</Button><Button type="button" variant="outline" size="sm" onClick={()=>onReuse(batch)}><RotateCcw/>{locale==='zh'?'再次使用':'Reuse'}</Button>{batch.status==='active'&&<Button type="button" variant="ghost" size="sm" className="ml-auto text-destructive" onClick={()=>askConfirm({title:locale==='zh'?'确认撤销这条 SQL 记录？':'Revert this SQL record?',description:locale==='zh'?'将撤销这次导入产生的字段范围，记录本身会保留。':'Field scopes created by this import will be reverted. The record stays in history.',confirmLabel:locale==='zh'?'撤销':'Revert',run:async()=>{await call('import.revert',{id:batch.id});await loadDetail();toast(locale==='zh'?'已撤销':'Reverted');}})}><RotateCcw/>{locale==='zh'?'撤销':'Revert'}</Button>}</div></div><div className="flex-1 space-y-6 overflow-y-auto p-6"><section><div className="mb-2 flex items-center gap-2"><FileCode2 className="size-3.5"/><strong className="text-xs">SQL</strong></div><pre className="max-h-72 overflow-auto rounded-xl bg-muted/50 p-4 text-[10px] leading-5">{batch.rawSql||'—'}</pre></section><section><div className="mb-2 flex items-center gap-2"><History className="size-3.5"/><strong className="text-xs">{locale==='zh'?'解析结果':'Parsed changes'}</strong><Badge variant="secondary" className="ml-auto">{items.length}</Badge></div><div className="divide-y rounded-xl border">{items.map(item=><div key={item.id} className="flex items-start gap-3 px-3 py-3"><span className={`mt-1 size-2 shrink-0 rounded-full ${item.result==='conflict'?'bg-destructive':item.result==='added'||item.result==='scope_removed'?'bg-emerald-500':'bg-muted-foreground/40'}`}/><span className="min-w-0 flex-1"><code className="block truncate text-[11px] font-semibold">{item.tableName}.{item.columnName}</code><span className="text-[10px] text-muted-foreground">{item.message||item.action}</span></span><Badge variant="outline">{item.result}</Badge></div>)}</div></section></div></>;
}

function ImportWorkspace({data,projects,scopeProject,scopeVersion,scopeEnvs,importName,importModule,importSql,importFile,importSourcePath,importGitCommit,busy,locale,t,chooseScopeProject,setScopeVersion,setScopeEnvs,setImportName,setImportModule,setImportSql,setImportSourcePath,setImportGitCommit,readFiles,runImport,projectVersions,projectEnvs,call,toast,askConfirm,onSelectImport,open}:{data:CatalogData;projects:Project[];scopeProject:string;scopeVersion:string;scopeEnvs:string[];importName:string;importModule:string;importSql:string;importFile:string;importSourcePath:string;importGitCommit:string;busy:boolean;locale:'zh'|'en';t:(typeof words)['zh']|(typeof words)['en'];chooseScopeProject:(id:string)=>void;setScopeVersion:(id:string)=>void;setScopeEnvs:(ids:string[])=>void;setImportName:(name:string)=>void;setImportModule:(id:string)=>void;setImportSql:(sql:string)=>void;setImportSourcePath:(path:string)=>void;setImportGitCommit:(commit:string)=>void;readFiles:(files:FileList|null)=>Promise<void>;runImport:()=>Promise<void>;projectVersions:(id:string)=>Version[];projectEnvs:(id:string)=>Environment[];call:(action:string,payload?:Record<string,unknown>)=>Promise<Record<string,unknown>>;toast:(message:string)=>void;askConfirm:(request:Confirmation)=>void;onSelectImport:(id:string)=>void;open:(kind:Exclude<ModalKind,null>,record?:Record<string,unknown>)=>void}){
  const ready=Boolean(importSql&&scopeProject&&scopeVersion&&scopeEnvs.length);
  const selectedVersion=data.versions.find(version=>version.id===scopeVersion);
  return <div className="grid gap-4 lg:grid-cols-[minmax(0,1.55fr)_minmax(320px,.75fr)]"><Card className="gap-0 overflow-hidden py-0"><div className="border-b px-5 py-4"><div className="flex items-center gap-2 text-xs font-semibold"><Import className="size-3.5"/>{locale==='zh'?'导入结构 SQL':'Import schema SQL'}</div><p className="mt-1 text-[11px] text-muted-foreground">{locale==='zh'?'先确定这份结构属于哪里，再粘贴或上传 CREATE TABLE / ALTER TABLE。':'Choose the exact target, then paste or upload CREATE TABLE / ALTER TABLE.'}</p></div><CardContent className="space-y-4 p-5"><Field label={locale==='zh'?'变更名称':'Change name'}><Input value={importName} onChange={event=>setImportName(event.target.value)} placeholder={locale==='zh'?'例如：客户等级字段调整':'e.g. Customer level update'}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={t.targetProject}><SelectField value={scopeProject} onValueChange={chooseScopeProject}><option value="">{locale==='zh'?'选择项目':'Choose project'}</option>{projects.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</SelectField></Field><Field label={t.targetVersion}><SelectField value={scopeVersion} onValueChange={setScopeVersion} disabled={!scopeProject}><option value="">{locale==='zh'?'选择版本':'Choose version'}</option>{projectVersions(scopeProject).map(version=><option key={version.id} value={version.id}>{version.name}</option>)}</SelectField></Field><Field label={t.targetEnvs}><ScopePicker envs={projectEnvs(scopeProject)} selected={scopeEnvs} onChange={setScopeEnvs} t={t}/></Field><div className="grid gap-2 text-xs font-medium"><span className="flex items-center">{t.ownerModule}<button type="button" className="ml-auto text-[10px] text-muted-foreground hover:text-foreground" onClick={()=>open('module')}><Plus className="mr-0.5 inline size-3"/>{locale==='zh'?'新增':'New'}</button></span><SelectField value={importModule} onValueChange={setImportModule}><option value="">{locale==='zh'?'暂不分类':'Unclassified'}</option>{data.modules.map(module=><option key={module.id} value={module.id}>{module.name}</option>)}</SelectField></div></div>{selectedVersion?.repository&&<div className="rounded-xl border bg-muted/20 p-3"><div className="flex items-center gap-2 text-[11px] font-medium"><GitBranch className="size-3.5"/><span className="min-w-0 flex-1 truncate">{selectedVersion.repository}{selectedVersion.gitRef?`@${selectedVersion.gitRef}`:''}</span></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label={locale==='zh'?'SQL 文件路径':'SQL file path'}><Input value={importSourcePath} onChange={event=>setImportSourcePath(event.target.value)} placeholder="sql/V018__customer.sql"/></Field><Field label="Commit"><Input value={importGitCommit} onChange={event=>setImportGitCommit(event.target.value)} placeholder={selectedVersion.gitCommit??'a1b2c3d'}/></Field></div></div>}<div className="relative"><Textarea value={importSql} onChange={event=>setImportSql(event.target.value)} className="min-h-80 resize-y rounded-xl bg-muted/25 p-4 font-mono text-xs leading-5" placeholder="CREATE TABLE customer ( … );"/><div className="absolute bottom-3 left-3 flex items-center gap-2"><label><input className="hidden" type="file" accept=".sql,text/plain" multiple onChange={event=>void readFiles(event.target.files)}/><Button asChild type="button" variant="secondary" size="sm"><span><Upload/>{t.upload}</span></Button></label>{importFile&&<Badge variant="secondary" className="max-w-64 truncate">{importFile}</Badge>}</div></div><div className="flex items-center justify-between"><span className="text-[10px] text-muted-foreground">{ready?(locale==='zh'?'将登记到 '+scopeEnvs.length+' 个环境':'Will register in '+scopeEnvs.length+' environments'):(locale==='zh'?'请完成项目、版本、环境和 SQL':'Project, version, environment, and SQL are required')}</span><Button disabled={busy||!ready} onClick={()=>void runImport()}><Import/>{busy?'…':t.runImport}</Button></div></CardContent></Card><Card className="gap-0 overflow-hidden py-0"><div className="flex items-center gap-2 border-b px-4 py-4"><FileCode2 className="size-3.5"/><strong className="text-xs">{t.recentImports}</strong><Badge variant="secondary" className="ml-auto">{data.imports.length}</Badge></div><CardContent className="divide-y p-0">{data.imports.map(batch=><div key={batch.id} className={`flex items-start gap-2 p-3 ${batch.status==='reverted'?'opacity-45':''}`}><button type="button" onClick={()=>onSelectImport(batch.id)} className="min-w-0 flex-1 rounded-lg p-1 text-left hover:bg-muted/50"><div className="flex items-center gap-2"><strong className="min-w-0 flex-1 truncate text-xs">{batch.name}</strong><ArrowRight className="size-3.5 text-muted-foreground"/></div><span className="mt-1 block truncate text-[10px] text-muted-foreground">{batch.projectName} · {batch.versionName}{batch.environmentNames?` · ${batch.environmentNames}`:''}</span><div className="mt-2 flex flex-wrap gap-1.5"><Badge variant="secondary">{locale==='zh'?'新增 '+batch.addedCount:'Added '+batch.addedCount}</Badge><Badge variant="outline">{locale==='zh'?'重复 '+batch.duplicateCount:'Duplicate '+batch.duplicateCount}</Badge><Badge variant={batch.conflictCount?'destructive':'outline'}>{locale==='zh'?'冲突 '+batch.conflictCount:'Conflict '+batch.conflictCount}</Badge></div></button>{batch.status==='active'&&<IconButton label={t.revert} onClick={()=>askConfirm({title:t.confirmRevert,description:t===words.zh?'将撤销这批导入产生的字段范围；仍被其他项目使用的字段会保留。':'This removes scopes created by the import. Fields still used by other projects are preserved.',confirmLabel:t.revert,run:async()=>{await call('import.revert',{id:batch.id});toast(t.saved);}})}><RotateCcw/></IconButton>}</div>)}{!data.imports.length&&<Empty text={t.noData}/>}</CardContent></Card></div>;
}

function SettingsView({data,t,open,remove,call,toast,askConfirm}:{data:CatalogData;t:(typeof words)['zh']|(typeof words)['en'];open:(kind:Exclude<ModalKind,null>,record?:Record<string,unknown>)=>void;remove:(entity:string,id:string)=>Promise<void>;call:(action:string,payload?:Record<string,unknown>)=>Promise<Record<string,unknown>>;toast:(message:string)=>void;askConfirm:(request:Confirmation)=>void}){return <div className="grid gap-4 md:grid-cols-2"><Card className="gap-0"><CardHeader className="flex-row items-center"><CardTitle className="flex items-center gap-2 text-sm"><Boxes className="size-4"/>{t.modules}<Badge variant="secondary">{data.modules.length}</Badge></CardTitle><div className="ml-auto"><IconButton label={t.addModule} onClick={()=>open('module')}><Plus/></IconButton></div></CardHeader><CardContent className="divide-y p-0">{data.modules.map(module=><div key={module.id} className="flex items-center gap-4 px-4 py-4"><div className="min-w-0 flex-1"><strong className="block truncate text-xs">{module.name}</strong><span className="text-[10px] text-muted-foreground">{module.code} · {module.tableCount} {t===words.zh?'张表':'tables'}</span></div><EntityMenu t={t} onEdit={()=>open('module',module as unknown as Record<string,unknown>)} onDelete={()=>void remove('module',module.id)}/></div>)}</CardContent></Card><Card className="gap-0"><CardHeader className="flex-row items-center"><CardTitle className="flex items-center gap-2 text-sm"><FolderGit2 className="size-4"/>GitHub<Badge variant="secondary">{data.repositories.length}</Badge></CardTitle><div className="ml-auto"><IconButton label={t.addSource} onClick={()=>open('repository')}><Plus/></IconButton></div></CardHeader><CardContent className="divide-y p-0">{data.repositories.map(source=><div key={source.id} className="flex items-center gap-4 px-4 py-4"><div className="min-w-0 flex-1"><strong className="block truncate text-xs">{source.name}</strong><span className="block truncate text-[10px] text-muted-foreground">{source.repository} · {source.branch} · {source.pathPattern}</span></div><EntityMenu t={t} onEdit={()=>open('repository',source as unknown as Record<string,unknown>)} onDelete={()=>void remove('repository',source.id)}/></div>)}{!data.repositories.length&&<Empty text={t.noData}/>}</CardContent></Card><Card className="md:col-span-2"><CardContent className="flex items-center justify-between"><span className="text-sm font-medium">{t.reset}</span><Button variant="destructive" size="icon" aria-label={t.reset} onClick={()=>askConfirm({title:t.confirmReset,description:t===words.zh?'字段、表、环境范围和全部导入记录都将被清空，项目与环境设置会保留。此操作无法撤销。':'All fields, tables, scopes, and import history will be cleared. Projects and environments stay. This cannot be undone.',confirmLabel:t.reset,run:async()=>{await call('catalog.reset');toast(t.saved);}})}><Trash2/></Button></CardContent></Card></div>;}

function PrimaryNav({view,nav,go}:{view:View;nav:{view:View;label:string;icon:typeof Search}[];go:(view:View)=>void}){
  const current=nav.find(item=>item.view===view)??nav[0];const CurrentIcon=current.icon;
  return <><nav className="hidden items-center rounded-lg bg-muted/70 p-0.5 md:flex">{nav.map(item=>{const ItemIcon=item.icon;const active=item.view===view;return <Button key={item.view} type="button" variant="ghost" size="sm" className={'h-8 gap-1.5 rounded-md px-3 text-xs '+(active?'bg-background shadow-sm hover:bg-background':'text-muted-foreground')} onClick={()=>go(item.view)}><ItemIcon className="size-3.5"/>{item.label}</Button>})}</nav><DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className="min-w-28 justify-between gap-2 md:hidden"><CurrentIcon/><span>{current.label}</span><ChevronDown className="size-3.5 text-muted-foreground"/></Button></DropdownMenuTrigger><DropdownMenuContent align="center">{nav.map(item=>{const ItemIcon=item.icon;return <DropdownMenuItem key={item.view} onClick={()=>go(item.view)}><ItemIcon/>{item.label}{item.view===view&&<Check className="ml-auto"/>}</DropdownMenuItem>})}</DropdownMenuContent></DropdownMenu></>;
}


function LanguageSwitcher({locale,chooseLocale}:{locale:'zh'|'en';chooseLocale:(locale:'zh'|'en')=>void}){return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" className="gap-2 px-2"><Languages/><span className="hidden sm:inline">{locale==='zh'?'中文':'English'}</span><span className="sm:hidden">{locale==='zh'?'中':'EN'}</span><ChevronDown className="hidden size-3.5 text-muted-foreground sm:block"/></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="min-w-36"><DropdownMenuItem onClick={()=>chooseLocale('zh')}>中文{locale==='zh'&&<Check className="ml-auto"/>}</DropdownMenuItem><DropdownMenuItem onClick={()=>chooseLocale('en')}>English{locale==='en'&&<Check className="ml-auto"/>}</DropdownMenuItem></DropdownMenuContent></DropdownMenu>;}

function CreateMenu({t,projects,open,go}:{t:(typeof words)['zh']|(typeof words)['en'];projects:Project[];open:(kind:Exclude<ModalKind,null>,record?:Record<string,unknown>)=>void;go:(view:View)=>void}){const projectId=projects[0]?.id;return <DropdownMenu><DropdownMenuTrigger asChild><Button size="icon" aria-label="New"><Plus/></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="min-w-44"><DropdownMenuItem onClick={()=>open('project')}><GitBranch/>{t.addProject}</DropdownMenuItem><DropdownMenuItem disabled={!projectId} onClick={()=>open('version',{projectId})}><Layers3/>{t.addVersion}</DropdownMenuItem><DropdownMenuItem disabled={!projectId} onClick={()=>open('environment',{projectId})}><Plus/>{t.addEnvironment}</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem onClick={()=>open('module')}><Boxes/>{t.addModule}</DropdownMenuItem><DropdownMenuItem onClick={()=>open('table')}><Table2/>{t.addTable}</DropdownMenuItem><DropdownMenuItem onClick={()=>open('field')}><Database/>{t.addField}</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem onClick={()=>go('imports')}><Import/>{t.runImport}</DropdownMenuItem></DropdownMenuContent></DropdownMenu>;}

function ScopePicker({envs,selected,onChange,t}:{envs:Environment[];selected:string[];onChange:(ids:string[])=>void;t:(typeof words)['zh']|(typeof words)['en']}){const chosen=envs.filter(env=>selected.includes(env.id));const all=envs.length>0&&chosen.length===envs.length;const summary=!envs.length?'—':!chosen.length?t.targetEnvs:all?(t===words.zh?`全部环境 · ${envs.length}`:`All environments · ${envs.length}`):chosen.length<=2?chosen.map(env=>env.name).join(' · '):(t===words.zh?`${chosen[0].name} 等 ${chosen.length} 个`:`${chosen[0].name} +${chosen.length-1}`);return <DropdownMenu><DropdownMenuTrigger asChild><Button type="button" variant="outline" disabled={!envs.length} className="w-full justify-between px-3 font-normal"><span className="flex min-w-0 items-center gap-2"><CircleDot className="size-3.5 text-muted-foreground"/><span className={`truncate text-xs ${chosen.length?'':'text-muted-foreground'}`}>{summary}</span></span><ChevronDown className="size-3.5 text-muted-foreground"/></Button></DropdownMenuTrigger><DropdownMenuContent align="start" className="min-w-(--radix-dropdown-menu-trigger-width)"><DropdownMenuCheckboxItem checked={all?true:chosen.length?'indeterminate':false} onSelect={event=>event.preventDefault()} onCheckedChange={checked=>onChange(checked===true?envs.map(env=>env.id):[])} className="h-8 text-xs font-medium"><span>{t===words.zh?'全部环境':'All environments'}</span><span className="ml-auto pr-5 text-[10px] text-muted-foreground">{envs.length}</span></DropdownMenuCheckboxItem><DropdownMenuSeparator/>{envs.map(env=><DropdownMenuCheckboxItem key={env.id} checked={selected.includes(env.id)} onSelect={event=>event.preventDefault()} onCheckedChange={checked=>onChange(checked===true?[...selected.filter(id=>id!==env.id),env.id]:selected.filter(id=>id!==env.id))} className="h-8 text-xs">{env.name}</DropdownMenuCheckboxItem>)}</DropdownMenuContent></DropdownMenu>;}
function SelectField({children,name,value,defaultValue,onValueChange,required,disabled,className,'aria-label':ariaLabel}:{children:ReactNode;name?:string;value?:string;defaultValue?:string;onValueChange?:(value:string)=>void;required?:boolean;disabled?:boolean;className?:string;'aria-label'?:string}){const options=Children.toArray(children).filter(isValidElement) as ReactElement<{value?:string|number;children?:ReactNode;disabled?:boolean}>[];const normalized=value??defaultValue??'';const rootValue=value===undefined?undefined:(value||emptySelect);const rootDefault=value===undefined?(defaultValue||emptySelect):undefined;return <Select name={name} value={rootValue} defaultValue={rootDefault} required={required} disabled={disabled} onValueChange={next=>onValueChange?.(next===emptySelect?'':next)}><SelectTrigger aria-label={ariaLabel} className={`h-9 w-full px-3 text-xs ${normalized?'':'text-muted-foreground'} ${className??''}`}><SelectValue/></SelectTrigger><SelectContent position="popper">{options.map((option,index)=>{const raw=String(option.props.value??'');if(required&&!raw)return null;return <SelectItem key={`${raw}-${index}`} value={raw||emptySelect} disabled={option.props.disabled} className="h-8 text-xs">{option.props.children}</SelectItem>;})}</SelectContent></Select>;}
function SearchSelect({name,defaultValue,placeholder,searchLabel,emptyLabel,options}:{name:string;defaultValue:string;placeholder:string;searchLabel:string;emptyLabel:string;options:{value:string;label:string;meta?:string}[]}){const [open,setOpen]=useState(false);const [value,setValue]=useState(defaultValue);const [filter,setFilter]=useState('');const selected=options.find(option=>option.value===value);const visible=options.filter(option=>`${option.label} ${option.meta??''}`.toLowerCase().includes(filter.trim().toLowerCase()));return <><input type="hidden" name={name} value={value}/><DropdownMenu open={open} onOpenChange={next=>{setOpen(next);if(!next)setFilter('');}}><DropdownMenuTrigger asChild><Button type="button" variant="outline" role="combobox" aria-expanded={open} className="w-full justify-between px-3 font-normal"><span className={`truncate text-xs ${selected?'':'text-muted-foreground'}`}>{selected?.label??placeholder}</span><ChevronDown className="size-3.5 text-muted-foreground"/></Button></DropdownMenuTrigger><DropdownMenuContent align="start" className="w-(--radix-dropdown-menu-trigger-width) p-1"><div className="p-1" onKeyDown={event=>event.stopPropagation()}><div className="relative"><Search className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"/><Input autoFocus value={filter} onChange={event=>setFilter(event.target.value)} placeholder={searchLabel} className="h-8 pl-8 text-xs"/></div></div><div className="max-h-56 overflow-y-auto">{visible.map(option=><DropdownMenuItem key={option.value} onSelect={()=>{setValue(option.value);setOpen(false);}} className="h-9"><span className="min-w-0 flex-1"><span className="block truncate text-xs">{option.label}</span>{option.meta&&<span className="block truncate text-[10px] text-muted-foreground">{option.meta}</span>}</span>{value===option.value&&<Check className="ml-auto"/>}</DropdownMenuItem>)}{!visible.length&&<div className="px-2 py-6 text-center text-xs text-muted-foreground">{emptyLabel}</div>}</div></DropdownMenuContent></DropdownMenu></>;}
function IconButton({label,children,onClick,active=false,danger=false}:{label:string;children:ReactNode;onClick:()=>void;active?:boolean;danger?:boolean}){return <Tooltip><TooltipTrigger asChild><Button type="button" variant={active?'secondary':'ghost'} size="icon" className={danger?'text-destructive':''} onClick={onClick} aria-label={label}>{children}</Button></TooltipTrigger><TooltipContent>{label}</TooltipContent></Tooltip>;}
function EntityMenu({t,onEdit,onDelete}:{t:(typeof words)['zh']|(typeof words)['en'];onEdit:()=>void;onDelete:()=>void}){return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" aria-label="Menu"><MoreHorizontal/></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onClick={onEdit}><Pencil/>{t.edit}</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem variant="destructive" onClick={onDelete}><Trash2/>{t.remove}</DropdownMenuItem></DropdownMenuContent></DropdownMenu>;}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="grid gap-2 text-xs font-medium"><span>{label}</span>{children}</label>;}
function Empty({text='—'}:{text?:string}){return <div className="grid min-h-28 place-items-center text-xs text-muted-foreground">{text}</div>;}
function ModalActions({busy,t,onClose,onDelete}:{busy:boolean;t:(typeof words)['zh']|(typeof words)['en'];onClose:()=>void;onDelete?:()=>void}){return <div className="flex items-center gap-2 pt-2">{onDelete&&<Button type="button" variant="ghost" size="icon" className="text-destructive" onClick={onDelete}><Trash2/></Button>}<span className="flex-1"/><Button type="button" variant="ghost" onClick={onClose}>{t.cancel}</Button><Button disabled={busy}>{busy?'…':t.save}</Button></div>;}
function modalTitle(kind:Exclude<ModalKind,null>,t:(typeof words)['zh']|(typeof words)['en'],editing:boolean){const add={project:t.addProject,environment:t.addEnvironment,version:t.addVersion,module:t.addModule,table:t.addTable,field:t.addField,repository:t.addSource}[kind];if(!editing)return add;const noun=t===words.zh?{project:'项目',environment:'环境',version:'版本',module:'模块',table:'数据表',field:'字段',repository:'来源'}[kind]:{project:'project',environment:'environment',version:'version',module:'module',table:'table',field:'field',repository:'source'}[kind];return t===words.zh?`${t.edit}${noun}`:`${t.edit} ${noun}`;}
